pub struct DownloadedCommand;

impl DownloadedCommand {
    #[allow(unused_variables)]
    pub fn execute(&self) -> Result<()> {
        let lib = LIB.get().expect("`cli-core` not initialized");
        cli_core_macros::load_core_symbols!(lib, print_content);
        let rd = match std::fs::read_dir(crate::local::plugins_dir()) {
            Ok(rd) => rd,
            Err(_) => {
                print_content(&"no plugins downloaded.".into());
                return Ok(());
            }
        };
        let mut names: Vec<String> = rd.flatten().filter_map(|e| {
            let n = e.file_name().to_string_lossy().to_string();
            if n.ends_with(".so") || n.ends_with(".dll") || n.ends_with(".dylib") { Some(n) } else { None }
        }).collect();
        names.sort();
        if names.is_empty() {
            print_content(&"no plugins downloaded.".into());
            return Ok(());
        }
        for n in names {
            print_content(&format!("  {}", n).into());
        }
        Ok(())
    }
}

